# ----- Handle conflicting options -----
def handle_conflicts(values, subcmd_opts, subcmd):
    # --dry-run vs --force
    if values.get('dry_run') and values.get('force'):
        usage = build_usage_with_flags(subcmd, subcmd_opts, values, ['dry_run'])
        clap_error("the argument '--dry-run' cannot be used with '--force'", usage)
    # --dump vs --no-dump
    if values.get('dump') and values.get('no_dump'):
        usage = build_usage_with_flags(subcmd, subcmd_opts, values, ['dump', 'force'])
        clap_error("the argument '--dump' cannot be used with '--no-dump'", usage)


def build_usage_with_flags(subcmd, opts, values, flags_to_include):
    """Build usage showing specific flags (used for conflict errors)."""
    parts = [PROG_NAME]
    if subcmd:
        parts.append(subcmd)
    for o in opts:
        if o.dest in flags_to_include and values.get(o.dest):
            if o.kind == 'flag':
                parts.append(o.long)
            else:
                parts.append(f"{o.long} {o.meta}")
    parts.append("<EXPRESSION>")
    parts.append("<REPLACEMENT>")
    parts.append("<PATH(S)>...")
    return " ".join(parts)


# ----- Replacement string processing (Rust regex style) -----
def _parse_replacement_chunks(repl):
    """
    Parse the replacement string, returning a list of chunks.
    Each chunk is either ('literal', text) or ('group', name-or-number).
    $$ -> literal $.
    $name or $number -> group reference (word chars greedily).
    ${name} -> explicit group reference.
    """
    out = []
    i = 0
    while i < len(repl):
        ch = repl[i]
        if ch == '$':
            if i + 1 < len(repl) and repl[i+1] == '$':
                out.append(('literal', '$'))
                i += 2
                continue
            if i + 1 < len(repl) and repl[i+1] == '{':
                # ${name}
                j = repl.find('}', i + 2)
                if j == -1:
                    # No closing brace - treat as literal $
                    out.append(('literal', '$'))
                    i += 1
                    continue
                name = repl[i+2:j]
                out.append(('group', name))
                i = j + 1
                continue
            # $name - take word chars greedily
            j = i + 1
            while j < len(repl) and (repl[j].isalnum() or repl[j] == '_'):
                j += 1
            if j == i + 1:
                # $<non-word> - treat as literal $
                out.append(('literal', '$'))
                i += 1
            else:
                name = repl[i+1:j]
                out.append(('group', name))
                i = j
        else:
            # Collect consecutive literal chars
            j = i
            while j < len(repl) and repl[j] != '$':
                j += 1
            out.append(('literal', repl[i:j]))
            i = j
    return out


def apply_replacement(match, repl_chunks, transform=None):
    """Build replacement string from parsed chunks and the match."""
    out_parts = []
    for kind, val in repl_chunks:
        if kind == 'literal':
            out_parts.append(val)
        else:  # group
            try:
                # Try as group number
                idx = int(val)
                try:
                    g = match.group(idx)
                except (IndexError, error):
                    g = None
                if g is None:
                    g = ""
            except ValueError:
                # Named group
                try:
                    g = match.group(val)
                except (IndexError, Exception):
                    g = None
                if g is None:
                    g = ""
            out_parts.append(g)
    result = "".join(out_parts)
    if transform == 'upper':
        result = result.upper()
    elif transform == 'lower':
        result = result.lower()
    elif transform == 'ascii':
        result = to_ascii(result)
    return result


