            if pattern[i:i+4] == '(?<=':
                raise RustRegexError(pattern, i, 4, "look-around, including look-ahead and look-behind, is not supported")
            if pattern[i:i+4] == '(?<!':
                raise RustRegexError(pattern, i, 4, "look-around, including look-ahead and look-behind, is not supported")
        i += 1


class RustRegexError(Exception):
    def __init__(self, pattern, pos, length, msg):
        self.pattern = pattern
        self.pos = pos
        self.length = length
        self.msg = msg

