    py_pattern = re.sub(r'\(\?<([A-Za-z_][A-Za-z0-9_]*)>', r'(?P<\1>', pattern)
    try:
        return re.compile(py_pattern)
    except re.error as e:
        # Emulate error. Position info not always accurate.
