    while i < len(pattern):
        ch = pattern[i]
        if ch == '\\' and i + 1 < len(pattern):
            nxt = pattern[i+1]
            if not in_class and nxt in '0123456789':
                # Backreference
                raise RustRegexError(pattern, i, 2, "backreferences are not supported")
            i += 2
            continue
        if ch == '[' and not in_class:
            in_class = True
            i += 1
            continue
        if ch == ']' and in_class:
            in_class = False
            i += 1
            continue
        if not in_class:
            # Look for (?=, (?!, (?<=, (?<!
            if pattern[i:i+3] == '(?=':
                raise RustRegexError(pattern, i, 3, "look-around, including look-ahead and look-behind, is not supported")
            if pattern[i:i+3] == '(?!':
                raise RustRegexError(pattern, i, 3, "look-around, including look-ahead and look-behind, is not supported")
            if pattern[i:i+4] == '(?<=':
                raise RustRegexError(pattern, i, 4, "look-around, including look-ahead and look-behind, is not supported")
            if pattern[i:i+4] == '(?<!':
                raise RustRegexError(pattern, i, 4, "look-around, including look-ahead and look-behind, is not supported")
        i += 1


class RustRegexError(Exception):
    def __init__(self, pattern, pos, length, msg):
        self.pattern = pattern
        self.pos = pos
        self.length = length
        self.msg = msg

    def format(self):
        caret = ' ' * self.pos + '^' * self.length
        return f"regex parse error:\n    {self.pattern}\n    {caret}\nerror: {self.msg}"


def compile_pattern(pattern):
    """Compile pattern, raising RustRegexError on failure."""
    validate_rust_regex(pattern)
    # Convert Rust regex (?P<name>...) - Python accepts this. Also (?<name>...) Rust style...
    # Python 3.11+ supports (?<name>...) but older doesn't. We can convert.
    # Rust supports both (?<name>...) and (?P<name>...). Python only supports (?P<name>...).
    # Let's convert (?<name>... to (?P<name>...
    py_pattern = re.sub(r'\(\?<([A-Za-z_][A-Za-z0-9_]*)>', r'(?P<\1>', pattern)
    try:
        return re.compile(py_pattern)
    except re.error as e:
        # Emulate error. Position info not always accurate.
        pos = getattr(e, 'pos', 0) or 0
        raise RustRegexError(pattern, pos, 1, str(e))
